import{_ as n,l as i,o as e,c as l,v as t,p as s,x as o,d as p,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const I=JSON.parse('{"title":"联合熵与互信息","description":"","frontmatter":{"title":"联合熵与互信息","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mutual-information.md","filePath":"cs/mutual-information.md","lastUpdated":1789023840000}'),m={name:"cs/mutual-information.md"};function c(u,a,X,_,Y,f){const r=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="联合熵与互信息" tabindex="-1">联合熵与互信息 <a class="header-anchor" href="#联合熵与互信息" aria-label="Permalink to &quot;联合熵与互信息&quot;">​</a></h1><div class="epigraph"><p>$X$ 与 $Y$ 共享多少信息，等于单独两份熵减去合在一起还剩下的不确定度。</p><footer>—— 据 Shannon, A Mathematical Theory of Communication, 1948 整理</footer></div><p>上一课<a href="/cs/entropy-bits">信息量与熵</a>钉死了自信息与 \\(H(X)\\)，并点名 \\(I(X;Y)=H(X)-H(X|Y)\\) 与容量式子，当时不展开。本课不重推 \\(-\\log p\\)，也不从信道框图另起综述。缺口是：<strong>两个</strong>随机变量怎么合在一张表上。没有联合熵，互信息只是一句定义，后课噪声信道没有「看见 \\(Y\\) 之后 \\(X\\) 还剩多少不确定」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(H(X)\\) 管一个源。存储、总线、后课纠错，都是「发出 \\(X\\)、收到 \\(Y\\)」。缺口因此不是更大的字母表，而是联合分布 \\(p(x,y)\\) 上的 \\(H(X,Y)\\)，以及链式法则 \\(H(X,Y)=H(X)+H(Y|X)\\)。互信息</p> \\[I(X;Y)=H(X)+H(Y)-H(X,Y)=H(X)-H(X|Y) \\]<p>对称，非负，当且仅当 \\(X\\perp Y\\) 时为零。上一课的「压缩下界」现在有了对照：相关的两路可以合起来压，独立则熵相加。</p><p>本课不证明 Shannon 第二定理，不把 \\(C=\\max I(X;Y)\\) 写成存在性论证。那是附录与信息论课，不插入主干。</p><h3 id="互信息不是「相关系数」" tabindex="-1">互信息不是「相关系数」 <a class="header-anchor" href="#互信息不是「相关系数」" aria-label="Permalink to &quot;互信息不是「相关系数」&quot;">​</a></h3><p>相关可以是非线性的：\\(I\\) 为零才叫独立（在有限字母表上）。只看 \\(\\mathrm{Cov}\\) 会漏异或一类依赖。也不把 \\(I(X;Y)\\) 当成语义上的「有用程度」：Shannon 不管意思。</p><p><span class="marginnote">Shannon 1948 用联合熵与条件熵写信道。维恩图式的 \\(H(X)\\)、\\(H(Y)\\)、\\(I(X;Y)\\) 是教学像，严格对象仍是联合分布上的和式。第一课的比特是符号位置；这里的比特仍是上一课的平均不确定度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>有限 \\(\\mathcal{X},\\mathcal{Y}\\)，\\(p(x,y)\\gt 0\\) 的项才进对数。\\(H(Y|X)=\\sum_x p(x)H(Y|X=x)\\)。数据处理不等式点到为止：加工 \\(Y\\) 不能增加关于 \\(X\\) 的互信息——后课特征与哈希若当「无损」，须另证可逆。</p>',13)),(e(),s(d,null,{default:o(()=>[h(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20HX%5B%22H(X)%22%5D%20--%3E%20JOINT%5B%22H(X%2CY)%22%5D%0A%20%20HY%5B%22H(Y)%22%5D%20--%3E%20JOINT%0A%20%20JOINT%20--%3E%20I%5B%22I(X%3BY)%22%5D%0A%20%20I%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%86%97%E4%BD%99%E6%8D%A2%E6%88%90%E8%B7%9D%E7%A6%BB%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>离散概率公理仍在<a href="/cs/discrete-probability">更后的课</a>才补全；本课继续用有限支撑上的 \\(p\\) 与期望。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有了 \\(I(X;Y)\\)，噪声被写成「信道」：\\(Y\\) 是 \\(X\\) 的污染版本，\\(I\\) 给出平均还剩多少可分辨。下一课纠错不从熵再起，而从码字几何起：熵管速率下界，距离管最坏翻转。两套尺子从此分叉，本课只把联合这一侧钉死。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入连续互信息、KL 散度全文、也不把大模型栏的注意力权重解释成 \\(I\\)。马尔可夫链 \\(X\\to Y\\to Z\\) 的数据处理只当一句话。</p><p>后课默认：谈到两路符号的共享信息，用 \\(I(X;Y)\\)；独立则互信息为零。检错要另加几何。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>联合熵满足链式法则；互信息是对称的共享不确定度。</li><li>\\(I=0\\) 当且仅当独立（有限字母表）。</li><li>压缩下界仍是熵；信道用互信息，纠错用距离，下一课换尺子。</li><li>出处：Shannon, <em>A Mathematical Theory of Communication</em>, 1948。</li></ul>',8))])}const T=n(m,[["render",c]]);export{I as __pageData,T as default};
